import{_ as i,o as r,c as n,a5 as a}from"./chunks/framework.a5no_H3L.js";const t="/unity/05-engineering-chapter-04-console.png",g="/unity/05-engineering-chapter-04-profiler-timeline.png",f=JSON.parse('{"title":"调试与 Profiler","description":"游戏出了 Bug 或跑起来卡，你知道要看 Console 和 Profiler，但不知道具体怎么用。读完这一篇，你能用日志、断点和 Profiler 定位问题，区分\\"找 Bug\\"和\\"找性能瓶颈\\"两件事。","frontmatter":{"type":"howto","level":"intermediate"},"headers":[],"relativePath":"unity/05-engineering/chapter-04-debugging-profiler.md","filePath":"unity/05-engineering/chapter-04-debugging-profiler.md"}'),l={name:"unity/05-engineering/chapter-04-debugging-profiler.md"};function d(s,e,o,c,p,u){return r(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="调试与-profiler" tabindex="-1" data-src-line="2" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">调试与 Profiler <a class="header-anchor" href="#调试与-profiler" aria-label="Permalink to &quot;调试与 Profiler&quot;">​</a></h1><p data-src-line="4" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">游戏出了 Bug 或跑起来卡，你知道要看 Console 和 Profiler，但不知道具体怎么用。读完这一篇，你能用日志、断点和 Profiler 定位问题，区分&quot;找 Bug&quot;和&quot;找性能瓶颈&quot;两件事。</p><h2 id="_1-找-bug-和找瓶颈是两回事" tabindex="-1" data-src-line="6" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">1. 找 Bug 和找瓶颈是两回事 <a class="header-anchor" href="#_1-找-bug-和找瓶颈是两回事" aria-label="Permalink to &quot;1. 找 Bug 和找瓶颈是两回事&quot;">​</a></h2><p data-src-line="8" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">先分清两类问题：</p><ul data-src-line="10" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><li data-src-line="10" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><strong>功能 Bug</strong>：行为不对，比如&quot;扣血扣了两倍&quot;&quot;按钮点了没反应&quot;。用日志和断点定位。</li><li data-src-line="11" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><strong>性能问题</strong>：行为对，但卡、掉帧、内存涨。用 Profiler 定位。</li></ul><p data-src-line="13" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">它们的工具不同：Bug 用 <code>Debug.Log</code> 和断点，性能用 Profiler。别用 <code>Debug.Log</code> 去排查性能（日志本身也有开销），也别用 Profiler 去找逻辑 Bug。</p><h2 id="_2-用日志定位-bug" tabindex="-1" data-src-line="15" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">2. 用日志定位 Bug <a class="header-anchor" href="#_2-用日志定位-bug" aria-label="Permalink to &quot;2. 用日志定位 Bug&quot;">​</a></h2><p data-src-line="17" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><code>Debug.Log</code> 是最常用的排查手段，在关键位置打印状态：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TakeDamage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> amount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    health </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> amount;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Debug.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$&quot;扣血 {</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">amount</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}，剩余 {</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">health</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 观察数值变化</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p data-src-line="27" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">Console 窗口（Window → General → Console）显示这些输出，并支持过滤：</p><p data-src-line="29" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><img src="`+t+'" alt="Console 窗口：普通日志、警告和错误三种消息类型"></p><p data-src-line="31" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><em>图源：<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/Console.html" target="_blank" rel="noreferrer">Unity 官方文档</a></em></p><ul data-src-line="33" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><li data-src-line="33" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">点击 <strong>Info / Warning / Error</strong> 切换显示类型，只看 Error 能快速定位报错。</li><li data-src-line="34" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">点击某条日志，能看到它的调用堆栈，点堆栈能跳到对应代码行。</li></ul><p data-src-line="36" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><code>Debug.Log</code> 适合快速确认&quot;代码有没有执行到、数值对不对&quot;，但它会留在代码里影响性能和整洁度，排查完应删除，或用 <code>#if UNITY_EDITOR</code> 包起来只在编辑器生效。</p><h2 id="_3-用断点精确定位" tabindex="-1" data-src-line="38" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">3. 用断点精确定位 <a class="header-anchor" href="#_3-用断点精确定位" aria-label="Permalink to &quot;3. 用断点精确定位&quot;">​</a></h2><p data-src-line="40" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">日志只能&quot;看&quot;，断点能&quot;停&quot;。在可疑代码行设断点，运行时程序停在那里，你可以逐行查看变量值。</p><p data-src-line="42" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">用 Visual Studio 或 Rider 打开项目：</p><ol data-src-line="44" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><li data-src-line="44" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">在可疑代码行左侧点一下，设断点（出现红点）。</li><li data-src-line="45" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">在 IDE 里点 <strong>Attach to Unity</strong>（附加到 Unity 进程）或直接点调试运行。</li><li data-src-line="46" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">游戏运行到断点处暂停，鼠标悬停变量查看当前值，用&quot;单步执行&quot;逐行推进。</li></ol><p data-src-line="48" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">断点适合&quot;日志打了但看不出问题&quot;的场景，能直接看到那一时刻所有变量的值。</p><h2 id="_4-用-profiler-定位性能瓶颈" tabindex="-1" data-src-line="50" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">4. 用 Profiler 定位性能瓶颈 <a class="header-anchor" href="#_4-用-profiler-定位性能瓶颈" aria-label="Permalink to &quot;4. 用 Profiler 定位性能瓶颈&quot;">​</a></h2><p data-src-line="52" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">游戏卡顿（掉帧）时，打开 <strong>Window → Analysis → Profiler</strong>：</p><p data-src-line="54" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><img src="'+g+'" alt="Profiler 的 Play 模式时间线：各帧的 CPU 耗时分布"></p><p data-src-line="56" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><em>图源：<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/Profiler.html" target="_blank" rel="noreferrer">Unity 官方文档</a></em></p><ol data-src-line="58" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><li data-src-line="58" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">点 Profiler 窗口的 <strong>Record</strong> 按钮开始记录。</li><li data-src-line="59" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">运行游戏，跑一段你觉得卡的部分。</li><li data-src-line="60" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">停止记录，分析数据。</li></ol><p data-src-line="62" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">Profiler 有几个关键区域：</p><ul data-src-line="64" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><li data-src-line="64" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><strong>CPU Usage</strong>：各系统（渲染、脚本、物理、动画）占用的 CPU 时间。哪个柱子高，哪个是瓶颈。</li><li data-src-line="65" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><strong>Rendering</strong>：渲染耗时，看 Draw Call 数量、三角形数量。</li><li data-src-line="66" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><strong>Memory</strong>：内存占用，看是否有泄漏（内存只涨不降）。</li></ul><p data-src-line="68" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">在 CPU 图里点最高的帧，下面会列出各函数耗时，找到你自己的脚本方法（名字下面带 <code>Scripts</code>），就能定位到&quot;哪个脚本哪一行在拖慢游戏&quot;。</p><p data-src-line="70" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">常见性能问题的定位：</p><table tabindex="0"><thead data-src-line="72" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><tr data-src-line="72" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><th>现象</th><th>常见原因</th><th>排查方向</th></tr></thead><tbody data-src-line="74" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><tr data-src-line="74" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><td>帧率低、CPU 高</td><td>脚本里每帧做昂贵操作</td><td>CPU 图里找耗时最高的脚本方法</td></tr><tr data-src-line="75" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><td>渲染慢</td><td>Draw Call 过多、模型面数高</td><td>Rendering 图里看 Draw Call 数量</td></tr><tr data-src-line="76" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><td>内存持续涨</td><td>物体只生成不销毁、资源泄漏</td><td>Memory 图看是否只涨不降</td></tr></tbody></table><h2 id="_5-一个完整排查流程" tabindex="-1" data-src-line="78" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">5. 一个完整排查流程 <a class="header-anchor" href="#_5-一个完整排查流程" aria-label="Permalink to &quot;5. 一个完整排查流程&quot;">​</a></h2><p data-src-line="80" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">以&quot;游戏越来越卡&quot;为例：</p><ol data-src-line="82" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md"><li data-src-line="82" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">打开 Profiler，Record 运行游戏，观察到帧率随时间下降。</li><li data-src-line="83" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">切到 CPU Usage，发现 <code>Update</code> 里某个脚本耗时越来越长。</li><li data-src-line="84" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">打开 Memory，发现对象数量持续增长——说明有物体只创建没销毁。</li><li data-src-line="85" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">回到代码，找到 <code>Instantiate</code> 的地方，确认对应逻辑有没有 <code>Destroy</code>。</li><li data-src-line="86" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">补上销毁逻辑，重新 Profiler 验证对象数量稳定。</li></ol><p data-src-line="88" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">这就是&quot;Profiler 定位 → 代码修复 → 复测&quot;的标准流程。</p><h2 id="_6-下一步" tabindex="-1" data-src-line="90" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">6. 下一步 <a class="header-anchor" href="#_6-下一步" aria-label="Permalink to &quot;6. 下一步&quot;">​</a></h2><p data-src-line="92" data-src-file="unity/05-engineering/chapter-04-debugging-profiler.md">调试能力齐了。最后解决多人协作的问题——Unity 项目怎么用版本控制：<a href="./chapter-05-version-control.html">版本控制与团队协作</a>。</p>',35)])])}const y=i(l,[["render",d]]);export{f as __pageData,y as default};
